/** Decodes one "U+XXXX" key to the character it names. */
function charOf(key: string): string {
  return String.fromCodePoint(Number.parseInt(key.slice(2), 16))
}

/** The server's ASCII-folding table, keyed by the character being folded. */
export const ASCII_FOLD_TABLE: ReadonlyMap<string, string> = new Map(
  Object.entries(ENTRIES).map(([key, value]) => [charOf(key), value] as const),
)
